css:
.caseopen-sim-container {
    padding: 28px;
    background: #f5f6f8;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}
.caseopen-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #2a3d6b 100%);
    color: #ffffff;
    padding: 36px 40px;
    border-radius: 6px;
    margin-bottom: 24px;
    border-bottom: 4px solid #c9a961;
    box-shadow: 0 6px 20px rgba(26,39,68,0.15);
}
.caseopen-sim-header-tag {
    font-size: 0.72rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #816d3d;
    font-weight: 700;
    margin-bottom: 10px;
}
.caseopen-sim-header h1 {
    font-size: 1.65rem;
    font-weight: 700;
    letter-spacing: -0.01em;
    margin: 0 0 6px 0;
}
.caseopen-sim-subtitle {
    font-size: 0.95rem;
    color: rgba(255,255,255,0.72);
    font-weight: 400;
}
.caseopen-sim-topbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    padding: 16px 24px;
    border-radius: 4px;
    margin-bottom: 24px;
    border: 1px solid #e2e5eb;
}
.caseopen-sim-period, .caseopen-sim-score {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 0.92rem;
    color: #66717f;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.caseopen-sim-period strong, .caseopen-sim-score strong {
    color: #1a2744;
    font-size: 1.15rem;
    font-weight: 700;
    letter-spacing: 0;
    text-transform: none;
}
.caseopen-sim-layout {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin-bottom: 24px;
    align-items: start;
}
.caseopen-sim-left { display: flex; flex-direction: column; gap: 16px; }
.caseopen-sim-brief {
    background: #ffffff;
    border: 1px solid #e2e5eb;
    padding: 24px 26px;
    border-radius: 4px;
    border-left: 4px solid #1a2744;
}
.caseopen-sim-brief-label {
    font-size: 0.7rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #66717f;
    font-weight: 700;
    margin-bottom: 10px;
}
.caseopen-sim-brief-title {
    font-size: 1.15rem;
    font-weight: 700;
    color: #1a2744;
    margin-bottom: 12px;
    line-height: 1.35;
}
.caseopen-sim-brief-text {
    font-size: 0.92rem;
    color: #3a4556;
    line-height: 1.65;
}
.caseopen-sim-coach {
    background: #fef9ed;
    border: 1px solid #ead9a9;
    padding: 20px 24px;
    border-radius: 4px;
    border-left: 4px solid #c9a961;
}
.caseopen-sim-coach-label {
    font-size: 0.7rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #7e6c32;
    font-weight: 700;
    margin-bottom: 8px;
}
.caseopen-sim-coach-text {
    font-size: 0.92rem;
    color: #3a3319;
    line-height: 1.6;
}
.caseopen-sim-controls {
    background: #ffffff;
    border: 1px solid #e2e5eb;
    padding: 26px 28px;
    border-radius: 4px;
}
.caseopen-sim-controls h3 {
    font-size: 0.8rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 18px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #e2e5eb;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}
.caseopen-sim-field { margin-bottom: 14px; }
.caseopen-sim-field label {
    display: block;
    font-size: 0.82rem;
    font-weight: 600;
    color: #1a2744;
    margin-bottom: 6px;
}
.caseopen-sim-field select,
.caseopen-sim-field input {
    background: #ffffff;
    border: 1px solid #c2c8d1;
    color: #1a2744;
    border-radius: 4px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.9rem;
    font-family: inherit;
    transition: border 0.2s ease, box-shadow 0.2s ease;
}
.caseopen-sim-field select:focus,
.caseopen-sim-field input:focus {
    outline: none;
    border-color: #1a2744;
    box-shadow: 0 0 0 2px rgba(26,39,68,0.12);
}
.caseopen-sim-field select option {
    background: #ffffff;
    color: #1a2744;
}
.caseopen-sim-controls .btn-primary {
    background: #1a2744;
    border: none;
    color: #ffffff;
    padding: 13px 22px;
    font-weight: 700;
    font-size: 0.85rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    border-radius: 4px;
    width: 100%;
    margin-top: 12px;
    transition: background 0.2s ease, transform 0.1s ease;
}
.caseopen-sim-controls .btn-primary:hover {
    background: #0f1a32;
}
.caseopen-sim-controls .btn-primary:active {
    transform: translateY(1px);
}
.caseopen-sim-controls .btn-outline-secondary {
    margin-top: 8px;
    width: 100%;
    color: #66717f;
    border: 1px solid #c2c8d1;
    background: transparent;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    padding: 8px 14px;
}
.caseopen-sim-scoreboard {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 12px;
    margin-bottom: 24px;
}
.caseopen-sim-kpi {
    background: #ffffff;
    border: 1px solid #e2e5eb;
    padding: 18px 14px;
    border-radius: 4px;
    text-align: center;
}
.caseopen-sim-kpi-label {
    font-size: 0.68rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #66717f;
    font-weight: 700;
    margin-bottom: 8px;
}
.caseopen-sim-kpi-value {
    font-size: 1.75rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1;
}
.caseopen-sim-kpi-total {
    background: #1a2744;
    color: #ffffff;
    border-color: #1a2744;
}
.caseopen-sim-kpi-total .caseopen-sim-kpi-label { color: #c9a961; }
.caseopen-sim-kpi-total .caseopen-sim-kpi-value {
    color: #ffffff;
    font-size: 0.95rem;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    padding-top: 8px;
    font-weight: 700;
}
.caseopen-sim-history {
    background: #ffffff;
    border: 1px solid #e2e5eb;
    padding: 22px 26px;
    border-radius: 4px;
    margin-bottom: 24px;
}
.caseopen-sim-history h3 {
    font-size: 0.8rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 14px 0;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}
.caseopen-sim-history table { margin: 0; font-size: 0.88rem; width: 100%; }
.caseopen-sim-history table thead { background: #f5f6f8; }
.caseopen-sim-history table th {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #66717f;
    padding: 10px 12px;
    border-bottom: 1px solid #e2e5eb;
    font-weight: 700;
    text-align: left;
}
.caseopen-sim-history table td {
    padding: 10px 12px;
    color: #3a4556;
    border-bottom: 1px solid #f0f2f5;
}
.caseopen-sim-chart {
    background: #ffffff;
    border: 1px solid #e2e5eb;
    padding: 24px;
    border-radius: 4px;
    height: 320px;
}

@media (max-width: 768px) {
    .caseopen-sim-container { padding: 16px; }
    .caseopen-sim-layout { grid-template-columns: 1fr; }
    .caseopen-sim-scoreboard { grid-template-columns: repeat(2, 1fr); }
    .caseopen-sim-header { padding: 24px 20px; }
    .caseopen-sim-header h1 { font-size: 1.25rem; }
    .caseopen-sim-topbar { flex-direction: column; gap: 8px; align-items: flex-start; }
}

/* --- EQIL 2026-08-06: focus visibility, reduced motion, completion panel --- */
:focus-visible {
    outline: 3px solid #1a2744;
    outline-offset: 2px;
    border-radius: 3px;
}
button:focus-visible,
select:focus-visible,
input:focus-visible {
    outline: 3px solid #1a2744;
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}
.caseopen-sim-actions {
    margin-top: 18px;
}
.caseopen-sim-completion {
    margin-top: 22px;
    padding: 24px 26px;
    background: #ffffff;
    border: 2px solid #1a2744;
    border-radius: 4px;
    color: #1a2744;
}
.caseopen-sim-completion h3 {
    margin: 0 0 10px;
    font-size: 1.4rem;
    font-weight: 700;
    color: #1a2744;
}
.caseopen-sim-completion h4 {
    margin: 18px 0 8px;
    font-size: 1rem;
    font-weight: 700;
    color: #1a2744;
}
.caseopen-sim-complete-score {
    font-size: 1.25rem;
    margin: 0 0 4px;
    color: #1a2744;
}
.caseopen-sim-complete-sub {
    font-size: 0.88rem;
    margin: 0;
    color: #454d5d;
}
.caseopen-sim-completion ul {
    margin: 0;
    padding-left: 20px;
}
.caseopen-sim-completion li {
    margin-bottom: 6px;
    line-height: 1.5;
    color: #1a2744;
}

