                this._renderCompletion();
                return false;
            }
            var clar = document.getElementById('clarifySelect');
            var sil  = document.getElementById('silenceSelect');
            var str  = document.getElementById('structureSelect');
            var cls  = document.getElementById('closeSelect');
            var con  = document.getElementById('convictionSelect');
            if (clar) decisions.clarify = clar.value;
            if (sil)  decisions.silenceSeconds = parseInt(sil.value);
            if (str)  decisions.structure = str.value;
            if (cls)  decisions.close = cls.value;
            if (con)  decisions.conviction = con.value;

            if (!decisions.clarify || !decisions.structure || !decisions.close || !decisions.conviction) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('incomplete_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;

            var clarifyMap = {
                'none':        { score: 0,  fb: 'fb_clar_none' },
                'industry':    { score: 8,  fb: 'fb_clar_industry' },
                'timehorizon': { score: 23, fb: 'fb_clar_time' },
                'metric':      { score: 25, fb: 'fb_clar_metric' }
            };
            var clarifyRes = clarifyMap[d.clarify] || clarifyMap['none'];

            var silenceScore = 0, silenceFb = 'fb_sil_none';
            if (d.silenceSeconds === 0) { silenceScore = 0;  silenceFb = 'fb_sil_none'; }
            else if (d.silenceSeconds <= 30)  { silenceScore = 10; silenceFb = 'fb_sil_short'; }
            else if (d.silenceSeconds <= 75)  { silenceScore = 25; silenceFb = 'fb_sil_good'; }
            else                               { silenceScore = 12; silenceFb = 'fb_sil_long'; }

            var structureMap = {
                'porters': { score: 4,  fb: 'fb_str_porters' },
                '4ps':     { score: 4,  fb: 'fb_str_4ps' },
                'mixed':   { score: 13, fb: 'fb_str_mixed' },
                'bespoke': { score: 25, fb: 'fb_str_bespoke' }
            };
            var structureRes = structureMap[d.structure] || structureMap['bespoke'];

            var closeMap = {
                'stop':       { score: 5,  fb: 'fb_close_stop' },
                'ask':        { score: 7,  fb: 'fb_close_ask' },
                'hypothesis': { score: 15, fb: 'fb_close_hyp' }
            };
            var closeRes = closeMap[d.close] || closeMap['stop'];

            var convictionMap = {
                'check_often': { score: 2,  fb: 'fb_con_check' },
                'balanced':    { score: 7,  fb: 'fb_con_bal' },
                'conviction':  { score: 10, fb: 'fb_con_conv' }
            };
            var convictionRes = convictionMap[d.conviction] || convictionMap['balanced'];

            var roundTotal = clarifyRes.score + silenceScore + structureRes.score + closeRes.score + convictionRes.score;

            state.domainState.totalScore      += roundTotal;
            state.domainState.scoreHistory.push(roundTotal);
            state.domainState.clarifyTotal    += clarifyRes.score;
            state.domainState.silenceTotal    += silenceScore;
            state.domainState.structureTotal  += structureRes.score;
            state.domainState.hypothesisTotal += closeRes.score;
            state.domainState.convictionTotal += convictionRes.score;

            var cumulative = state.domainState.totalScore;
            var maxSoFar   = state.currentPeriod * 100;
            var ratio      = cumulative / maxSoFar;
            var signal = 'signal_reject';
            if (ratio >= 0.85)      signal = 'signal_strong';
            else if (ratio >= 0.7)  signal = 'signal_offer';
            else if (ratio >= 0.5)  signal = 'signal_maybe';
            state.domainState.offerSignal = signal;

            var ds0 = state.domainState;
            ds0.overallScore = this._composite(ds0.totalScore, (ds0.scoreHistory || []).length || 1);
            // platform score: the same running composite the final verdict reports (total so far over 100 per round played, already 0-100)
            ds0.performance = Object.assign({}, ds0.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(Number(ds0.overallScore) || 0))) });

            var self = this;
            var nextPeriod = (state.currentPeriod || 1) + 1;
            if (nextPeriod > this.ROUNDS.length) ds0.finished = true;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
                self._updateCoachFeedback([clarifyRes.fb, silenceFb, structureRes.fb, closeRes.fb, convictionRes.fb]);
                self._updateSignal(signal);
            }, 400);

            return {
                period: state.currentPeriod,
                clarifyScore: clarifyRes.score,
                silenceScore: silenceScore,
                structureScore: structureRes.score,
                closeScore: closeRes.score,
                convictionScore: convictionRes.score,
                roundTotal: roundTotal,
                cumulativeScore: cumulative,
                signal: signal
            };
        }

        _updateBriefing(state) {
            if (!window.mySimulation || !window.mySimulation.t) return;
            var period = (state && state.currentPeriod) || 1;
            var dsNow = (state && state.domainState) ||
                        (window.mySimulation.state ? window.mySimulation.state.domainState : null) || {};
            if (dsNow.finished || period > this.ROUNDS.length) {
                this._renderCompletion();
                return;
            }
            var controlsEl = document.getElementById('decisionControls');
            if (controlsEl) controlsEl.style.display = '';
            var actionsEl = document.getElementById('simActions');
            if (actionsEl) actionsEl.style.display = '';
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = window.mySimulation.t.bind(window.mySimulation);
            var titleEl = document.getElementById('caseTitle');
            var briefEl = document.getElementById('caseBriefing');
            if (titleEl) titleEl.innerHTML = t(round.titleKey);
            if (briefEl) briefEl.innerHTML = t(round.briefKey);
        }

        _updateCoachFeedback(keys) {
            var el = document.getElementById('coachFeedback');
            if (!el) return;
            var t = window.mySimulation.t.bind(window.mySimulation);
            var html = '';
            for (var i = 0; i < keys.length; i++) {
                if (html.length) html += '<br><br>';
                html += t(keys[i]);
            }
            el.innerHTML = html;
        }

        _updateSignal(signal) {
            var el = document.getElementById('offerKpi');
            if (!el) return;
            var t = window.mySimulation.t.bind(window.mySimulation);
            el.innerHTML = t(signal);
        }

