        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var hist = ds.scoreHistory || [];
            var labels = hist.map((_, i) => 'R' + (i + 1));
            this._labelChart();
            return {
                maturityChart: {
                    labels: labels,
                    datasets: [{ label: this._chartText('chart_maturity_ds'), data: hist }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var total = history.reduce((s, r) => s + ((r.results && r.results.roundTotal) || 0), 0);
            var avg = total / history.length;
            var ratio = total / (history.length * 100);

            var t = this._t();
            var performance = 'cosplay';
            if (ratio >= 0.85)      performance = 'strong';
            else if (ratio >= 0.7)  performance = 'offer_track';
            else if (ratio >= 0.5)  performance = 'rushed';
            var overallScore = this._composite(total, history.length);

            var insights = [];
            if (performance === 'strong') {
                insights.push(t('insight_strong_1'));
                insights.push(t('insight_strong_2'));
            } else if (performance === 'offer_track') {
                insights.push(t('insight_offer_1'));
            } else if (performance === 'rushed') {
                insights.push(t('insight_rushed_1'));
            } else {
                insights.push(t('insight_cosplay_1'));
                insights.push(t('insight_cosplay_2'));
            }

            return {
                totalScore: total,
                avgScore: Math.round(avg),
                maxPossible: history.length * MAX_ROUND_SCORE,
                overallScore: overallScore,
                composite: overallScore,
                score: overallScore,
                performance: performance,
                performanceKey: performance,
                performanceLabel: t('perf_' + performance),
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.clarifyScore < 10)    return window.mySimulation.t('hint_clarify');
            if (results.silenceScore < 10)    return window.mySimulation.t('hint_silence');
            if (results.structureScore < 10)  return window.mySimulation.t('hint_structure');
            if (results.closeScore < 10)      return window.mySimulation.t('hint_hypothesis');
            if (results.convictionScore < 5)  return window.mySimulation.t('hint_conviction');
            return window.mySimulation.t('hint_strong');
        }

